<?php /** Single post template. @package Samanvay */ get_header(); while ( have_posts() ) : the_post(); ?>
<main id="primary"><header class="page-header"><div class="site-container"><span class="eyebrow"><?php the_category( ', ' ); ?></span><h1><?php the_title(); ?></h1><p><?php echo esc_html( get_the_date() ); ?> · <?php echo esc_html( get_the_author() ); ?></p></div></header><div class="content-area"><div class="site-container content-layout"><article><div class="entry-content"><?php if ( has_post_thumbnail() ) : the_post_thumbnail( 'large' ); endif; the_content(); wp_link_pages(); ?></div><?php the_post_navigation(); if ( comments_open() || get_comments_number() ) { comments_template(); } ?></article><?php get_sidebar(); ?></div></div></main>
<?php endwhile; get_footer(); ?>
